import csv
import io
import re
from typing import List, Dict, Any


def parse_csv(raw_csv: str) -> Dict[str, Any]:
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )
    records = []
    for record in reader:
        if not record or not any(cell.strip() for cell in record):
            continue
        records.append(record)

    if not records:
        return {"columns": [], "rows": []}

    width = 3

    def normalized(record):
        record = list(record)
        if len(record) > width:
            record = record[:width - 1] + [",".join(record[width - 1:])]
        return (record + [""] * width)[:width]

    def looks_like_header(index):
        row = normalized(records[index])
        if not all(cell.strip() for cell in row):
            return False
        if not any(re.search(r"[A-Za-z]", cell) for cell in row):
            return False
        if index + 1 >= len(records):
            return index == 0

        following = normalized(records[index + 1])
        first = following[0].strip()
        last = following[-1].strip()
        first_looks_like_value = bool(
            re.search(r"\d", first) or re.fullmatch(r"[-+]?\d+(?:\.\d+)?", first)
        )
        last_looks_like_value = bool(
            re.fullmatch(r"[-+]?\d+(?:\.\d+)?", last)
        )
        has_header_style = any(
            "_" in cell or re.search(r"\b(?:date|name|amount|total|id)\b", cell, re.I)
            for cell in row
        )
        return first_looks_like_value or last_looks_like_value or has_header_style

    header_index = next(
        (i for i in range(len(records)) if looks_like_header(i)),
        next((i for i, row in enumerate(records) if len(row) == width), 0),
    )
    columns = normalized(records[header_index])
    rows = [normalized(record) for record in records[header_index + 1:]]

    return {"columns": columns, "rows": rows}
